// 图生图API服务
import { API_CONFIG } from './config';

/**
 * 将图片文件转换为Base64格式
 * @param {string} filePath - 图片文件路径
 * @returns {Promise<string>} - Base64格式的图片
 */
function convertImageToBase64(filePath) {
  return new Promise((resolve, reject) => {
    // 检查是否在浏览器环境中
    if (typeof window !== 'undefined' && window.FileReader) {
      // 创建一个新的图片对象
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = function() {
        // 创建canvas元素
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        canvas.width = img.width;
        canvas.height = img.height;
        // 在canvas上绘制图片
        ctx.drawImage(img, 0, 0);
        // 将canvas内容转换为Base64
        const base64 = canvas.toDataURL('image/jpeg');
        resolve(base64);
      };
      img.onerror = function() {
        reject(new Error('图片加载失败'));
      };
      // 设置图片源
      img.src = filePath;
    } else if (typeof uni !== 'undefined' && uni.getFileSystemManager) {
      // 在uni-app环境中使用原来的方法
      uni.getFileSystemManager().readFile({
        filePath,
        encoding: 'base64',
        success: (res) => {
          resolve(`data:image/jpeg;base64,${res.data}`);
        },
        fail: (err) => {
          reject(new Error(`图片转换失败: ${err.errMsg}`));
        }
      });
    } else {
      reject(new Error('不支持的运行环境，无法转换图片'));
    }
  });
}

/**
 * 文+图生图转换
 * @param {string} personalImage - 个人图像路径
 * @param {string} exhibitionImage - 展览图像路径
 * @param {string} prompt - 编辑指令
 * @param {string} size - 图像尺寸
 * @param {number} guidanceScale - 引导比例
 * @returns {Promise<object>} - 生成结果
 */
export async function imageToImage(personalImage, exhibitionImage, prompt = '把这两个图片融合', size = 'adaptive', guidanceScale = 5.5) {
  try {
      // 将两张图片转换为Base64格式
      const base64PersonalImage = await convertImageToBase64(personalImage);
      const base64ExhibitionImage = await convertImageToBase64(exhibitionImage);

      const response = await uni.request({
        url: `${API_CONFIG.BASE_URL}${API_CONFIG.IMAGE_TO_IMAGE_ENDPOINT}`,
        method: 'POST',
        header: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${API_CONFIG.API_KEY}`
        },
        data: {
          model: API_CONFIG.IMAGE_TO_IMAGE_MODEL,
          prompt,
          image: base64PersonalImage,
          exhibition_image: base64ExhibitionImage,
          response_format: 'url',
          size,
          guidance_scale: guidanceScale,
          num_images: 2 // 请求生成两张图片
        }
      });

    console.log('API响应内容:', response);

    if (response.statusCode === 200) {
      return response.data;
    } else {
      throw new Error(`API请求失败: ${response.statusCode}, ${response.data?.error?.message || '未知错误'}`);
    }
  } catch (error) {
    console.error('图像生成失败:', error);
    throw error;
  }
}